class Solution {
public:
    string lexGreaterPermutation(string s, string target) {
        int n = s.size();
        int cnt[26] = {0};
        for (char ch : s) cnt[ch - 'a']++;

        int bump = -1, bumpC = 0;
        int snap[26];
        bool broke = false;

        for (int i = 0; i < n; i++) {
            int t = target[i] - 'a';
            for (int c = t + 1; c < 26; c++) {
                if (cnt[c]) {
                    bump = i;
                    bumpC = c;
                    for (int k = 0; k < 26; k++) snap[k] = cnt[k];
                    break;
                }
            }
            if (cnt[t]) {
                cnt[t]--;
            } else {
                broke = true;
                break;
            }
        }

        if (bump < 0) return "";

        string res = target.substr(0, bump);
        res += char('a' + bumpC);
        snap[bumpC]--;
        for (int c = 0; c < 26; c++)
            res.append(snap[c], char('a' + c));
        return res;
    }
};
